    (1,1,"TCP reliable delivery","Order what TCP does to deliver a byte stream reliably.",["Break application bytes into transport data","Number the bytes","Send and wait for acknowledgments","Retransmit missing data","Reassemble bytes in order for the destination application"],"Numbering and acknowledgments let the endpoints identify loss and restore order."),
    (1,6,"TCP close states","Order a simplified active close path.",["Connection is ESTABLISHED","One endpoint sends FIN","Peer acknowledges the FIN","Peer later sends its FIN","Final ACK is sent","Active closer remains briefly in TIME_WAIT"],"The two directions close separately, and TIME_WAIT protects a later connection from delayed segments."),
    (2,10,"One web exchange","Order a basic HTTP interaction.",["Browser resolves the server name if needed","Client opens the transport connection","Client sends an HTTP request","Server returns status, headers, and optional body","Client renders or uses the response"],"Name resolution and transport prepare the path; HTTP carries the actual request and response."),
    (2,14,"Email journey","Order one simplified email path.",["User writes mail in an MUA","MUA submits it using SMTP","MTAs relay it toward the recipient server","Recipient uses IMAP or POP3 to access it"],"The user agent is the interface; transfer agents relay; an access protocol retrieves or synchronizes."),
    (3,22,"DHCP DORA","Order the main messages used to obtain a lease.",["Client broadcasts Discover","Server sends Offer","Client sends Request","Server sends Acknowledgment"],"Discover asks, Offer proposes, Request chooses, and ACK confirms."),
