    (3,27,"DNS referral path","Order a common recursive lookup performed for a client.",["Client asks its recursive resolver","Resolver asks a root server","Root refers it to the TLD servers","TLD refers it to the authoritative server","Authoritative server returns the record","Resolver caches and returns the answer"],"The client delegates the work to a recursive resolver, which follows iterative referrals."),
    (4,30,"Routing one packet","Order a router's simplified forwarding decision.",["Receive the frame and inspect the IP destination","Find all matching routing-table prefixes","Choose the longest matching prefix","Use the selected next hop or exit interface","Build a new link-layer frame for that hop and send it"],"The packet keeps its end destination while each hop receives a new local link-layer wrapper."),
    (4,33,"Link-state routing","Order a simplified link-state process.",["Discover neighbors and link costs","Advertise link-state information","Build a topology database","Run a shortest-path calculation","Install best routes in the routing table"],"Routers first learn the map, then calculate paths from it."),
    (5,45,"Reusable subnet worksheet","Put the ordinary IPv4 subnet-solving steps in order.",["Write the current prefix and the original parent prefix","Find host bits and borrowed bits","Convert the current prefix to a mask","Calculate total addresses, usable hosts, and subnet count","Find the interesting octet and block size","Locate the containing network boundary","Set host bits to 1 for broadcast","Take network + 1 and broadcast − 1 for the host range"],"The order prevents a common mistake: counting subnets without knowing the parent prefix."),
